doc.code:
let key = "b";
let o = {
    a: 1,
    "Customer Name": "hello",
    [key]: true
};
o.c = true;
assert(o.a === 1);
assert(property_get(o, "Customer Name") === "hello");
assert(o.b === true);
assert(property_exists(o, "c") === true);

section.code:
let o = { "name": "ada", "id": 42 };

keys(o);      /* ["name", "id"] — property names */
values(o);    /* ["ada", 42] */
entries(o);   /* [ ["name", "ada"], ["id", 42] ] */

/* Method form */
o->keys();
o->values();
o->entries();

for (let pair of entries(o)) {
    /* pair[0] is the name, pair[1] is the value */
}

doc.code:
let a = [10, 20, 30];
assert(a[0] === 10);
assert(length(a) === 3);
assert(at(a, -1) === 30);   /* last element */
assert(is_nullish(at(a, 99))); /* out of range → undefined */

section.code:
let a = ["a", , "b"];
assert(length(a) === 3);
assert(a[0] === "a");
assert(a[1] === undefined);
assert(a[2] === "b");

let b = ["a", undefined, "b"];
assert(a[1] === b[1]);

let a = [1];
assert(push(a, 2, 3) === 3);  /* [1, 2, 3]; the new length */
assert(pop(a) === 3);         /* [1, 2] */
assert(unshift(a, 0) === 3);  /* [0, 1, 2]; the new length */
assert(shift(a) === 0);       /* [1, 2] */

/* empty pop/shift → undefined */
assert(is_nullish(pop([])));

/* bulk append of arrays */
let b = [];
add_entries(b, [1, 2], [3]);

let a = [];
a[0] = "x";             /* length becomes 1 */
a[1] = "y";             /* length becomes 2 */
a[0] = "z";             /* replace */
/* a[5] = "no";        → error: index is past the end */

let a = create_array(3);
assert(length(a) === 3);
assert(a[0] === undefined);
a[1] = "ready";

let zeros = create_array(3, 0);   /* [0, 0, 0] */

let ids = array<integer>(1, 2);
push(ids, 3);
/* push(ids, "4");  → error: an array of integer can not hold a string */

let a = ["a", "b", "c", "d"];
let removed = splice(a, 1, 2, "X");
/* a is ["a", "X", "d"]; removed is ["b", "c"] */

let a = [1, 2];
freeze(a);
/* push(a, 3);  → error: array is immutable */

let o = { "x": 1 };
o->freeze();
/* o.y = 2;  → error */

/* Pure reads still work */
assert(length(keys(o)) === 1);
assert(at(a, 0) === 1);

let isEven = function (n) { return n % 2 === 0; };
assert(every([2, 4, 6], isEven) === true);
assert(some([1, 2, 3], isEven) === true);
assert(every([], isEven) === true);
assert(some([], isEven) === false);

assert(eq([1, 2, 3]->map(function (v, i) { return v * 10 + i; }), [10, 21, 32]));
assert(find_index(["a", "b"], function (v) { return v === "b"; }) === 1);
assert([1, 2, 3]->reduce(function (acc, v) { return acc + v; }) === 6);
assert(eq(map([1, -2], abs<integer>), [1, 2]));

let a = [10, 9, 1];
sort(a);
assert(eq(a, [1, 9, 10]));
sort(a, function (x, y) { return y - x; });
assert(eq(a, [10, 9, 1]));

const b = [3, 1, 2];
assert(eq(to_sorted(b), [1, 2, 3]));
assert(eq(with_at(b, -1, 9), [3, 1, 9]));
assert(eq(b, [3, 1, 2]));

assert(eq(flat([1, [2, [3]]], -1), [1, 2, 3]));
assert(eq(group_by([1, 2, 3], function (v) {
    return v % 2 === 0 ? "even" : "odd";
}), { odd: [1, 3], even: [2] }));
assert(eq(from_entries([["a", 1]]), { a: 1 }));

